def arrayNesting(A):
    max_length = 0
    visited = [False] * len(A)

    for i in range(len(A)):
        if not visited[i]:
            current_length = 0
            k = i
            while not visited[k]:
                visited[k] = True
                k = A[k]
                current_length += 1
            max_length = max(max_length, current_length)

    return max_length
